package com.faraz.expensemanagement.security; import com.faraz.expensemanagement.repo.UserRepo; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.nio.charset.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.web.*; import org.springframework.stereotype.*; import org.springframework.web.filter.OncePerRequestFilter;
@Service public class Jwt{final SecretKey key; final long exp; public Jwt(@Value("${app.jwt.secret}")String s,@Value("${app.jwt.expiration-ms}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));exp=e;}public String make(String e){return Jwts.builder().subject(e).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key).compact();}public String email(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}
